- chong_chi_dinh: {'muc_do': 4, 'cho_con_bu': 'Do tính chất gây đột biến và gây ung thư của thuốc.', 'mang_thai': 'Thuốc gây quái thai, chỉ dùng kèm với biện pháp ngừa thai (nam và nữ) có hiệu lực'}
- can_nhac_nguy_co_loi_ich: {'muc_do': 3, 'tre_em': 'Chỉ dùng trong trường hợp cần thiết tuyệt đối, vì tác dụng gây ung thư khi dùng lâu dài.'}
- than_trong: {'muc_do': 2, 'benh_ve_mau': 'Do độc với tuỷ xương, dùng rất thận trọng ở người bệnh đang hoặc đã bị chứng giảm tế bào.', 'suy_than': 'Điều chỉnh liều tuỳ theo độ thanh lọc creatinin, do thuốc đào thải qua nước tiểu.', 'truong_hop_khac': 'Tiền sử tâm thần.'}
- can_theo_doi: {'muc_do': 1, 'nguoi_cao_tuoi': 'Vì nguy cơ tổn hại đến chức năng thận ở người cao tuổi.'}

